// Generated by allium:propagate from spec/recipe-ideas.allium (ReplaceCandidates' per-candidate checks and invariant
// CandidatesHaveTitles). Do not edit by hand: change the spec and propagate.
import fc from "fast-check";
import { describe, expect, it } from "vitest";
import {
  defaultIdeaConfig,
  editIdea,
  keepIdea,
  noteIdea,
  pickCandidate,
  recipeIdeaId,
  replaceCandidates,
  reviewCandidates,
  useOwnRecipe,
  type IdeaConfig,
  type RecipeIdea,
} from "../../src/ideas/idea.js";
import { memberId } from "../../src/shared/ids.js";

const ME = memberId("me");
const T0 = Date.parse("2026-11-01T12:00:00Z");
const HOUR = 3_600_000;

const good = (n: number) => ({ title: `Rezept ${n}`, link: `https://example.org/rezept-${n}`, summary: `Kurz ${n}` });

describe("ReplaceCandidates: each proposed candidate is checked on its own", () => {
  const config = defaultIdeaConfig;

  it("drops a candidate whose title is empty, only whitespace, or missing", () => {
    const found = reviewCandidates(
      {
        candidates: [
          good(1),
          { title: "", link: "https://example.org/empty", summary: "" },
          { title: "   \t\n ", link: "https://example.org/blank", summary: "" },
          { link: "https://example.org/missing", summary: "" },
          { title: 42, link: "https://example.org/number", summary: "" },
          good(2),
        ],
      },
      config,
    );
    expect(found.map((c) => c.title)).toEqual(["Rezept 1", "Rezept 2"]);
  });

  it("drops a candidate whose title is empty once stripped of links and markup", () => {
    const found = reviewCandidates(
      {
        candidates: [
          { title: "<b></b>", link: "https://example.org/markup", summary: "" },
          { title: "https://evil.example/x", link: "https://example.org/link", summary: "" },
          { title: "<i> </i> www.evil.example", link: "https://example.org/both", summary: "" },
          good(3),
        ],
      },
      config,
    );
    expect(found).toEqual([good(3)]);
  });

  it("keeps the other candidates when one is dropped, for a missing title as for a bad link", () => {
    const found = reviewCandidates(
      {
        candidates: [
          { title: " ", link: "https://example.org/a", summary: "" },
          good(1),
          { title: "Kein Link", link: "javascript:alert(1)", summary: "" },
          good(2),
        ],
      },
      config,
    );
    expect(found).toEqual([good(1), good(2)]);
  });

  it("brings no candidate when every title is dropped, so the idea keeps its candidates and its clock", () => {
    const idea = must(noteIdea({ id: recipeIdeaId("i1"), member: ME, title: "Kürbis" }, T0));
    const before = must(replaceCandidates(idea, [good(9)], T0 + HOUR, config));
    const found = reviewCandidates(
      {
        candidates: [
          { title: "", link: "https://example.org/a", summary: "x" },
          { title: "<p></p>", link: "https://example.org/b" },
        ],
      },
      config,
    );
    expect(found).toEqual([]);
    expect(replaceCandidates(before, found, T0 + 2 * HOUR, config)).toEqual({ ok: false, reason: "no_candidates" });
  });

  it("leaves at most the configured number of candidates after the drops", () => {
    const answer = {
      candidates: [
        { title: "", link: "https://example.org/x", summary: "" },
        ...Array.from({ length: 8 }, (_, i) => good(i + 1)),
      ],
    };
    const found = reviewCandidates(answer, { ...config, maxCandidates: 3 });
    expect(found).toHaveLength(3);
    expect(found.every((c) => c.title.trim() !== "")).toBe(true);
  });
});

function must<T>(r: { ok: true; value: T } | { ok: false; reason: string }): T {
  if (!r.ok) throw new Error(`rejected: ${r.reason}`);
  return r.value;
}

/** Titles as a model might send them: plain, blank, markup, links, or not text at all. */
const title: fc.Arbitrary<unknown> = fc.oneof(
  fc.string({ maxLength: 10 }),
  fc.constantFrom("", " ", "\t\n", "<b></b>", "<i> </i>", "https://evil.example/x", "www.evil.example", "Kürbis"),
  fc.constant(undefined),
  fc.integer(),
);

const answer: fc.Arbitrary<unknown> = fc.record({
  candidates: fc.array(
    fc.record({
      title,
      link: fc.constantFrom("https://example.org/r", "http://example.org/r", "javascript:x", ""),
      summary: fc.string({ maxLength: 10 }),
    }),
    { maxLength: 9 },
  ),
});

type Cmd =
  | { t: "research"; answer: unknown }
  | { t: "edit"; title: string }
  | { t: "pick"; candidate: number }
  | { t: "own" }
  | { t: "keep" };

const cmd: fc.Arbitrary<Cmd> = fc.oneof(
  fc.record({ t: fc.constant("research" as const), answer }),
  fc.record({ t: fc.constant("edit" as const), title: fc.string({ maxLength: 8 }) }),
  fc.record({ t: fc.constant("pick" as const), candidate: fc.integer({ min: -1, max: 6 }) }),
  fc.record({ t: fc.constant("own" as const) }),
  fc.record({ t: fc.constant("keep" as const) }),
);

/** One step of the idea's life; a rejected rule leaves the idea as it was. */
function apply(idea: RecipeIdea, c: Cmd, now: number, config: IdeaConfig): RecipeIdea {
  switch (c.t) {
    case "research": {
      const r = replaceCandidates(idea, reviewCandidates(c.answer, config), now, config);
      return r.ok ? r.value : idea;
    }
    case "edit": {
      const r = editIdea(idea, { member: ME, title: c.title }, now);
      return r.ok ? r.value : idea;
    }
    case "pick": {
      const r = pickCandidate(idea, { member: ME, candidate: c.candidate }, now);
      return r.ok ? r.value.idea : idea;
    }
    case "own":
      return useOwnRecipe(idea, { member: ME }, now);
    case "keep": {
      const r = keepIdea(idea, { member: ME }, now, config);
      return r.ok ? r.value : idea;
    }
  }
}

describe("invariant CandidatesHaveTitles", () => {
  it("holds after every step, whatever titles the model answers with", () => {
    fc.assert(
      fc.property(
        fc.array(fc.tuple(cmd, fc.nat(24 * 7 * 12)), { maxLength: 25 }),
        fc.integer({ min: 1, max: 6 }),
        (steps, maxCandidates) => {
          const config: IdeaConfig = { ...defaultIdeaConfig, maxCandidates };
          let idea = must(noteIdea({ id: recipeIdeaId("i"), member: ME, title: "Kürbis" }, T0));
          let now = T0;
          for (const [c, hours] of steps) {
            now += hours * HOUR;
            idea = apply(idea, c, now, config);
            for (const candidate of idea.candidates) expect(candidate.title.trim()).not.toBe("");
          }
        },
      ),
    );
  });
});
